  defstruct [:open]

  @type t :: %__MODULE__{
          open: integer()
        }

  def decode_open(value) when is_integer(value), do: value
  def decode_open(_), do: {:error, "Unexpected type when decoding Open.open"}

  def encode_open(value) when is_integer(value), do: value
  def encode_open(_), do: {:error, "Unexpected type when encoding Open.open"}

  def from_map(m) do
    %Open{
      open: decode_open(m["open"]),
    }
  end

  def from_json(json) do
    json
          |> Jason.decode!()
          |> from_map()
  end

  def to_map(struct) do
    %{
      "open" => struct.open,
    }
  end

  def to_json(struct) do
    struct
          |> to_map()
          |> Jason.encode!()
  end
end

