defmodule TopLevel do
  @enforce_keys [:dummy, :obj1, :obj2, :obj3, :obj4, :obj5, :obj6]
  defstruct [:dummy, :obj1, :obj2, :obj3, :obj4, :obj5, :obj6]

  @type t :: %__MODULE__{
          dummy: integer(),
          obj1: Obj1.t(),
          obj2: Obj2.t(),
          obj3: Obj3.t(),
          obj4: Obj4.t(),
          obj5: Obj5.t(),
          obj6: Obj6.t()
        }

  def decode_dummy(value) when is_integer(value), do: value
  def decode_dummy(_), do: {:error, "Unexpected type when decoding TopLevel.dummy"}

  def encode_dummy(value) when is_integer(value), do: value
  def encode_dummy(_), do: {:error, "Unexpected type when encoding TopLevel.dummy"}

  def from_map(m) do
    %TopLevel{
      dummy: decode_dummy(m["dummy"]),
      obj1: Obj1.from_map(m["obj1"]),
      obj2: Obj2.from_map(m["obj2"]),
      obj3: Obj3.from_map(m["obj3"]),
      obj4: Obj4.from_map(m["obj4"]),
      obj5: Obj5.from_map(m["obj5"]),
      obj6: Obj6.from_map(m["obj6"]),
    }
  end

  def from_json(json) do
    json
          |> Jason.decode!()
          |> from_map()
  end

  def to_map(struct) do
    %{
      "dummy" => struct.dummy,
      "obj1" => Obj1.to_map(struct.obj1),
      "obj2" => Obj2.to_map(struct.obj2),
      "obj3" => Obj3.to_map(struct.obj3),
      "obj4" => Obj4.to_map(struct.obj4),
      "obj5" => Obj5.to_map(struct.obj5),
      "obj6" => Obj6.to_map(struct.obj6),
    }
  end

  def to_json(struct) do
    struct
          |> to_map()
          |> Jason.encode!()
  end
end
